function redactedSnapshot(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    email: null,
    name: REDACTED_NAME,
    phone: null,
    external_reference: null,
    status: 'deleted',
  };
}

function redactedBilling(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    email: null,
    name: REDACTED_NAME,
    phone: null,
    externalReference: null,
    metadata: {},
  };
}

export class ErasureRepository {
  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByIdempotencyKey(merchantId: string, key: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`,
      [merchantId, key],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, id: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, id],
    );
    return result.rows[0];
  }

  async create(
    client: PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3) RETURNING *`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async markProcessing(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,updated_at=now() WHERE id=$1`,
      [requestId],
    );
  }

  async markCompleted(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(client: PoolClient, requestId: string, errorCode: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed',last_error=$2,updated_at=now() WHERE id=$1`,
      [requestId, errorCode],
    );
  }

  async markRetryPending(client: PoolClient, requestId: string, errorCode: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='pending',last_error=$2,updated_at=now() WHERE id=$1`,
      [requestId, errorCode],
    );
  }

  async customerExistsAndActive(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT status FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    if (!result.rowCount) return false;
    return result.rows[0]!.status !== 'deleted';
  }

  /** Performs every per-customer cleanup that must be durable in PostgreSQL. */
  async runCleanup(
    client: PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<CleanupResult> {
    const summary: CleanupSummary = {
      customerRedacted: false,
      addressesRemoved: 0,
      contactsRemoved: 0,
      paymentMethodsRemoved: 0,
      supportParticipantsRemoved: 0,
      supportMessagesRemoved: 0,
      providerCustomerMappingsRemoved: 0,
      providerSandboxCustomersRemoved: 0,
      notificationPreferencesRemoved: 0,
      paymentIntentsAnonymized: 0,
      invoicesAnonymized: 0,
      refundsAnonymized: 0,
      notificationsAnonymized: 0,
      emailDeliveriesAnonymized: 0,
      analyticsEventsAnonymized: 0,
      documentManifestsAnonymized: 0,
      outboxEventsRedacted: 0,
    };

    const redactedCustomer = await client.query(
      `UPDATE customers.customers
       SET email=$3,name=$4,phone=NULL,metadata='{}'::jsonb,external_reference=$5,
           status='deleted',version=version+1,updated_at=now()
       WHERE merchant_id=$1 AND id=$2 AND status<>'deleted'
       RETURNING id`,
      [merchantId, customerId, REDACTED_EMAIL, REDACTED_NAME, `redacted-${customerId.slice(0, 8)}`],
    );
    summary.customerRedacted = Boolean(redactedCustomer.rowCount);

    const removedAddresses = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.addressesRemoved = Number(removedAddresses.rows[0]?.count ?? 0);

    const removedContacts = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.contactsRemoved = Number(removedContacts.rows[0]?.count ?? 0);

    const removedMethods = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.paymentMethodsRemoved = Number(removedMethods.rows[0]?.count ?? 0);

    const removedParticipants = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.support_participants WHERE customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.supportParticipantsRemoved = Number(removedParticipants.rows[0]?.count ?? 0);

    const removedMessages = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.support_messages
         WHERE merchant_id=$1 AND author_type='customer' AND author_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.supportMessagesRemoved = Number(removedMessages.rows[0]?.count ?? 0);

    const removedMappings = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM customers.provider_customer_mappings
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.providerCustomerMappingsRemoved = Number(removedMappings.rows[0]?.count ?? 0);

    const removedPreferences = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM operations.notification_preferences
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.notificationPreferencesRemoved = Number(removedPreferences.rows[0]?.count ?? 0);

    const anonymizedIntents = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE payments.payment_intents
         SET customer_snapshot=$3
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId, redactedSnapshot(customerId)],
    );
    summary.paymentIntentsAnonymized = Number(anonymizedIntents.rows[0]?.count ?? 0);

    const anonymizedInvoices = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE payments.invoices
         SET billing_snapshot=$3
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId, redactedBilling(customerId)],
    );
    summary.invoicesAnonymized = Number(anonymizedInvoices.rows[0]?.count ?? 0);

    const anonymizedRefunds = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE payments.refunds
         SET customer_email=$3
         WHERE merchant_id=$1 AND payment_intent_id IN (
           SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
         ) RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId, REDACTED_EMAIL],
    );
    summary.refundsAnonymized = Number(anonymizedRefunds.rows[0]?.count ?? 0);

    const anonymizedNotifications = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE operations.notifications
         SET customer_id=NULL,destination=$3
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId, REDACTED_EMAIL],
    );
    summary.notificationsAnonymized = Number(anonymizedNotifications.rows[0]?.count ?? 0);

    const anonymizedEmails = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE operations.email_deliveries
         SET customer_id=NULL,destination=$3
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId, REDACTED_EMAIL],
    );
    summary.emailDeliveriesAnonymized = Number(anonymizedEmails.rows[0]?.count ?? 0);

    const anonymizedAnalytics = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE operations.analytics_events
         SET customer_id=NULL,email=NULL
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId],
    );
    summary.analyticsEventsAnonymized = Number(anonymizedAnalytics.rows[0]?.count ?? 0);

    const anonymizedManifests = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE operations.document_manifests
         SET customer_id=NULL
         WHERE merchant_id=$1 AND customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [merchantId, customerId],
    );
    summary.documentManifestsAnonymized = Number(anonymizedManifests.rows[0]?.count ?? 0);

    const redactedOutbox = await client.query<{ count: string }>(
      `WITH updated AS (
         UPDATE operations.outbox_events
         SET payload=jsonb_build_object('customerId',aggregate_id,'redacted',true)
         WHERE aggregate_type='customer' AND aggregate_id=$1 AND status='pending' RETURNING 1
       )
       SELECT count(*)::text count FROM updated`,
      [customerId],
    );
    summary.outboxEventsRedacted = Number(redactedOutbox.rows[0]?.count ?? 0);

    const removedSandbox = await client.query<{ count: string }>(
      `WITH removed AS (
         DELETE FROM provider_sandbox.customers
         WHERE merchant_id=$1 AND payflow_customer_id=$2 RETURNING 1
       )
       SELECT count(*)::text count FROM removed`,
      [merchantId, customerId],
    );
    summary.providerSandboxCustomersRemoved = Number(removedSandbox.rows[0]?.count ?? 0);

    return { summary, redactedEmail: REDACTED_EMAIL, redactedName: REDACTED_NAME };
  }

  async importObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT m.object_key FROM operations.document_manifests m
       JOIN customers.customer_imports i ON i.merchant_id=m.merchant_id
       WHERE m.merchant_id=$1 AND i.merchant_id=$1 AND m.document_type='customer_import'
         AND i.id::text=ANY(string_to_array(m.metadata->>'importId',','))
         AND m.metadata->>'importId' IS NOT NULL
         AND i.id IN (SELECT id FROM customers.customer_imports WHERE merchant_id=$1)
         AND m.metadata->>'sourceCustomerId'=$2`,
      [merchantId, customerId],
    );
    if (result.rowCount) return result.rows.map((row) => row.object_key);
    return await this.fallbackImportKeys(merchantId, customerId);
  }

  private async fallbackImportKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type='customer_import'`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  async knownEmailDestinations(customerId: string): Promise<string[]> {
    const destinations = new Set<string>();
    const customer = await pool.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE id=$1`, [customerId],
    );
    if (customer.rows[0]?.email) destinations.add(customer.rows[0].email);
    const notifications = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.notifications WHERE customer_id=$1`, [customerId],
    );
    for (const row of notifications.rows) destinations.add(row.destination);
    const emails = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.email_deliveries WHERE customer_id=$1`, [customerId],
    );
    for (const row of emails.rows) destinations.add(row.destination);
    const refunds = await pool.query<{ customer_email: string }>(
      `SELECT customer_email FROM payments.refunds
       WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$1)`,
      [customerId],
    );
    for (const row of refunds.rows) if (row.customer_email) destinations.add(row.customer_email);
    return [...destinations];
  }

  static toView(row: ErasureRequestRow): ErasureRequestView {
    return {
      id: row.id,
      customerId: row.customer_id,
      status: row.status,
      attempts: row.attempts,
      createdAt: row.created_at.toISOString(),
      updatedAt: row.updated_at.toISOString(),
      completedAt: row.completed_at ? row.completed_at.toISOString() : null,
      lastError: row.last_error,
    };
  }
}"}

{"security_risk":"LOW","summary":"Create erasure service","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { randomUUID } from 'node:crypto';
import type pg from 'pg';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { CustomerRepository } from './repository.js';
import { ErasureRepository, type CleanupSummary, type ErasureRequestView } from './erasure-repository.js';

export interface ErasureRequestInput {
  merchantId: string;
  customerId: string;
  idempotencyKey: string;
  correlationId?: string;
}

export interface ProcessErasureInput {
  merchantId: string;
  customerId: string;
  requestId: string;
}

export class ErasureConflictError extends Error {
  constructor() { super('idempotency_key_customer_mismatch'); this.name = 'ErasureConflictError'; }
}

export class ErasureCustomerNotFoundError extends Error {
  constructor() { super('customer_not_found'); this.name = 'ErasureCustomerNotFoundError'; }
}

export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async createOrLookup(input: ErasureRequestInput): Promise<{ view: ErasureRequestView; enqueued: boolean }> {
    const correlationId = input.correlationId ?? randomUUID();
    return await transaction(async (client) => {
      const existingForKey = await client.query(
        `SELECT * FROM customers.erasure_requests
         WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
        [input.merchantId, input.idempotencyKey],
      );
      const existingKeyRow = existingForKey.rows[0];
      if (existingKeyRow) {
        if (existingKeyRow.customer_id !== input.customerId) throw new ErasureConflictError();
        return { view: ErasureRepository.toView(existingKeyRow), enqueued: false };
      }
      const customer = await client.query<{ id: string; status: string }>(
        `SELECT id,status FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
        [input.merchantId, input.customerId],
      );
      const customerRow = customer.rows[0];
      if (!customerRow) throw new ErasureCustomerNotFoundError();
      const existingForCustomer = await client.query(
        `SELECT * FROM customers.erasure_requests
         WHERE merchant_id=$1 AND customer_id=$2`,
        [input.merchantId, input.customerId],
      );
      const existingCustomerRow = existingForCustomer.rows[0];
      if (existingCustomerRow) {
        return { view: ErasureRepository.toView(existingCustomerRow), enqueued: false };
      }
      const created = await this.repository.create(client, input.merchantId, input.customerId, input.idempotencyKey);
      await this.customers.audit(client, input.merchantId, input.customerId, 'customer.erasure.requested', correlationId, {
        requestId: created.id,
      });
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED,
        aggregateType: 'erasure_request',
        aggregateId: created.id,
        merchantId: input.merchantId,
        correlationId,
        payload: { requestId: created.id, customerId: input.customerId },
      });
      return { view: ErasureRepository.toView(created), enqueued: true };
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestView | undefined> {
    const row = await this.repository.findById(merchantId, requestId);
    return row ? ErasureRepository.toView(row) : undefined;
  }

  /** Runs the durable cleanup steps inside a single transaction and emits the erasure event. */
  async process(input: ProcessErasureInput): Promise<{ completed: boolean; summary: CleanupSummary | null }> {
    return await transaction(async (client) => {
      await this.repository.markProcessing(client, input.requestId);
      const request = await client.query<{ id: string; customer_id: string; status: string }>(
        `SELECT id,customer_id,status FROM customers.erasure_requests
         WHERE id=$1 AND merchant_id=$2 FOR UPDATE`,
        [input.requestId, input.merchantId],
      );
      const row = request.rows[0];
      if (!row) return { completed: false, summary: null };
      if (row.status === 'completed') return { completed: true, summary: null };
      const result = await this.repository.runCleanup(client, input.merchantId, row.customer_id);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASED,
        aggregateType: 'erasure_request',
        aggregateId: row.id,
        merchantId: input.merchantId,
        correlationId: randomUUID(),
        payload: {
          requestId: row.id,
          customerId: row.customer_id,
          redactedEmail: result.redactedEmail,
          summary: result.summary,
        },
      });
      await this.customers.audit(client, input.merchantId, row.customer_id, 'customer.erasure.completed', randomUUID(), {
        requestId: row.id,
        summary: result.summary,
      });
      await this.repository.markCompleted(client, row.id);
      return { completed: true, summary: result.summary };
    });
  }

  /** Best-effort cleanup of caches, search projections, captures, and dev-only mailpit messages. */
  async finalizeExternalState(input: ProcessErasureInput): Promise<void> {
    const destinations = await this.repository.knownEmailDestinations(input.customerId);
    for (const destination of destinations) {
      try { await deleteMailpitMessagesForRecipient(destination); }
      catch { /* mailpit is dev-only and best-effort */ }
    }
    try {
