const headers = { authorization: `Bearer ${apiKey}`, 'content-type': 'application/json' };

interface Result<T> { status: number; body: T; }
async function api<T>(method: string, path: string, body?: unknown, extraHeaders: Record<string, string> = {}): Promise<Result<T>> {
  const init: RequestInit = { method, headers: { ...headers, ...extraHeaders } };
  if (body !== undefined) init.body = JSON.stringify(body);
  const response = await fetch(`${gateway}${path}`, init);
  const responseBody = await response.json() as T;
  return { status: response.status, body: responseBody };
}

const sleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

async function pollUntilSettled<T extends { status: string }>(path: string, allowed: Set<string>): Promise<Result<T>> {
  for (let attempt = 0; attempt < 60; attempt += 1) {
    const result = await api<T>(`GET`, path);
    if (result.status === 200 && allowed.has(result.body.status)) return result;
    await sleep(500);
  }
  throw new Error(`timed out waiting for ${path} to reach ${[...allowed].join('|')}`);
}

